package org.apache.commons.jxpath.ri.model.jdom;

import org.jdom.CDATA;
import org.jdom.Content;
import org.jdom.Element;
import org.jdom.Namespace;
import org.jdom.ProcessingInstruction;
import org.jdom.Text;
import org.junit.Assert;
import org.junit.Test;

import java.lang.reflect.Method;
import java.util.Locale;

public class AsPathTests {

    private static JDOMNodePointer pointer(Object node) {
        return new JDOMNodePointer(node, Locale.US);
    }

    private static JDOMNodePointer pointer(Object node, String id) {
        return new JDOMNodePointer(node, Locale.US, id);
    }

    private static void setParent(JDOMNodePointer child, JDOMNodePointer parent) {
        try {
            Method m = org.apache.commons.jxpath.ri.model.NodePointer.class.getDeclaredMethod(
                    "setParent",
                    org.apache.commons.jxpath.ri.model.NodePointer.class
            );
            m.setAccessible(true);
            m.invoke(child, parent);
        } catch (NoSuchMethodException e) {
            try {
                java.lang.reflect.Field f = org.apache.commons.jxpath.ri.model.NodePointer.class.getDeclaredField("parent");
                f.setAccessible(true);
                f.set(child, parent);
            } catch (Exception ex) {
                throw new AssertionError(ex);
            }
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static Element element(String name) {
        return new Element(name);
    }

    private static Element namespacedElement(String name, String prefix, String uri) {
        return new Element(name, Namespace.getNamespace(prefix, uri));
    }

    private static ProcessingInstruction pi(String target, String data) {
        return new ProcessingInstruction(target, data);
    }

    @Test
    public void idTakesPrecedenceAndEscapesQuotes() {
        Element node = element("root");
        JDOMNodePointer p = pointer(node, "a'b\"c");

        Assert.assertEquals("id('a\\'b\"c')", p.asPath());
    }

    @Test
    public void rootElementWithoutParentProducesRelativeElementPath() {
        Element node = element("root");
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("root[1]", p.asPath());
    }

    @Test
    public void childElementAppendsToParentPathWithSlash() {
        Element parentNode = element("parent");
        JDOMNodePointer parent = pointer(parentNode);

        Element childNode = element("child");
        JDOMNodePointer child = pointer(childNode);
        setParent(child, parent);

        Assert.assertEquals("parent[1]/child[1]", child.asPath());
    }

    @Test
    public void namespacedElementWithKnownPrefixUsesPrefixedQName() {
        Element node = namespacedElement("child", "p", "urn:test");
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("p:child[1]", p.asPath());
    }

    @Test
    public void namespacedElementWithoutPrefixFallsBackToNodeTest() {
        Element node = namespacedElement("child", "", "urn:test");
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("node()[1]", p.asPath());
    }

    @Test
    public void textNodeProducesTextPath() {
        Text text = new Text("value");
        JDOMNodePointer p = pointer(text);

        Assert.assertEquals("/text()[1]", p.asPath());
    }

    @Test
    public void cdataNodeProducesTextPath() {
        CDATA cdata = new CDATA("value");
        JDOMNodePointer p = pointer(cdata);

        Assert.assertEquals("/text()[1]", p.asPath());
    }

    @Test
    public void processingInstructionProducesTargetedPath() {
        ProcessingInstruction instruction = pi("xml-stylesheet", "type='text/xsl'");
        JDOMNodePointer p = pointer(instruction);

        Assert.assertEquals("/processing-instruction('xml-stylesheet')[1]", p.asPath());
    }

    @Test
    public void nonSpecialNodeWithParentDelegatesToParentOnly() {
        Content content = new Text("x");
        JDOMNodePointer parent = pointer(element("root"));
        JDOMNodePointer child = pointer(content);
        setParent(child, parent);

        Assert.assertEquals("root[1]/text()[1]", child.asPath());
    }

    @Test
    public void nullNamespacePrefixDoesNotUseColonOrQName() {
        Element node = new Element("local", Namespace.NO_NAMESPACE);
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("local[1]", p.asPath());
    }

    @Test
    public void asPathReturnsEmptyStringForUnsupportedNodeTypesWithoutParent() {
        class DummyContent extends Content {
            @Override
            public String getValue() {
                return "";
            }

            @Override
            public Content clone() {
                return this;
            }
        }

        Content dummy = new DummyContent();
        JDOMNodePointer p = pointer(dummy);

        Assert.assertEquals("", p.asPath());
    }
}

package org.apache.commons.jxpath.ri.model.jdom;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.Locale;

import org.apache.commons.jxpath.ri.model.NodePointer;
import org.jdom.CDATA;
import org.jdom.Comment;
import org.jdom.Document;
import org.jdom.Element;
import org.jdom.Namespace;
import org.jdom.ProcessingInstruction;
import org.jdom.Text;
import org.junit.Test;

public class AsPathTests {

    private static JDOMNodePointer newPointer(NodePointer parent, Object node) {
        try {
            Constructor<JDOMNodePointer> c = JDOMNodePointer.class.getConstructor(NodePointer.class, Object.class);
            return c.newInstance(parent, node);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static JDOMNodePointer newPointer(Object node, Locale locale) {
        try {
            Constructor<JDOMNodePointer> c = JDOMNodePointer.class.getConstructor(Object.class, Locale.class);
            return c.newInstance(node, locale);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static JDOMNodePointer newPointer(Object node, Locale locale, String id) {
        try {
            Constructor<JDOMNodePointer> c = JDOMNodePointer.class.getConstructor(Object.class, Locale.class, String.class);
            return c.newInstance(node, locale, id);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static String callAsPath(JDOMNodePointer pointer) {
        try {
            Method m = JDOMNodePointer.class.getMethod("asPath");
            return (String) m.invoke(pointer);
        } catch (InvocationTargetException e) {
            Throwable cause = e.getCause();
            if (cause instanceof RuntimeException) {
                throw (RuntimeException) cause;
            }
            if (cause instanceof Error) {
                throw (Error) cause;
            }
            throw new AssertionError(cause);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    @Test
    public void testIdPathEscapesQuotesInId() {
        Element root = new Element("root");
        JDOMNodePointer pointer = newPointer(root, Locale.ENGLISH, "a'b");
        assertEquals("id('a\\'b')", callAsPath(pointer));
    }

    @Test
    public void testIdPathTakesPrecedenceOverNodeType() {
        ProcessingInstruction pi = new ProcessingInstruction("target", "data");
        JDOMNodePointer pointer = newPointer(pi, Locale.ENGLISH, "abc");
        assertEquals("id('abc')", callAsPath(pointer));
    }

    @Test
    public void testElementWithoutParentProducesEmptyPathForRootElement() {
        Element root = new Element("root");
        JDOMNodePointer pointer = newPointer(root, Locale.ENGLISH);
        assertEquals("", callAsPath(pointer));
    }

    @Test
    public void testElementWithParentAndNoNamespaceProducesIndexedQNamePath() {
        Element parentElement = new Element("parent");
        Document doc = new Document(parentElement);
        JDOMNodePointer parentPointer = newPointer(doc, Locale.ENGLISH);

        Element child = new Element("child");
        parentElement.addContent(child);

        JDOMNodePointer childPointer = newPointer(parentPointer, child);
        String path = callAsPath(childPointer);

        assertNotNull(path);
        assertTrue(path.startsWith("/"));
        assertTrue(path.contains("child["));
        assertTrue(path.endsWith("]"));
    }

    @Test
    public void testElementWithNamespaceAndKnownPrefixUsesPrefixedQName() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element parent = new Element("parent");
        Document doc = new Document(parent);
        JDOMNodePointer parentPointer = newPointer(doc, Locale.ENGLISH);

        Element child = new Element("child", ns);
        parent.addContent(child);

        JDOMNodePointer childPointer = newPointer(parentPointer, child);
        String path = callAsPath(childPointer);

        assertEquals("/p:child[1]", path);
    }

    @Test
    public void testElementWithNamespaceAndUnknownPrefixFallsBackToNodeTest() {
        Namespace ns = Namespace.getNamespace("urn:test");
        Element parent = new Element("parent");
        Document doc = new Document(parent);
        JDOMNodePointer parentPointer = newPointer(doc, Locale.ENGLISH);

        Element child = new Element("child", ns);
        parent.addContent(child);

        JDOMNodePointer childPointer = newPointer(parentPointer, child);
        String path = callAsPath(childPointer);

        assertTrue(path.startsWith("/node()["));
        assertTrue(path.endsWith("1]") || path.endsWith("1"));
        assertTrue(!path.contains(":child"));
    }

    @Test
    public void testTextNodeProducesTextAxisPath() {
        Text text = new Text("hello");
        JDOMNodePointer pointer = newPointer(text, Locale.ENGLISH);
        String path = callAsPath(pointer);

        assertEquals("/text()[1]", path);
    }

    @Test
    public void testCdataNodeTreatedAsTextNode() {
        CDATA cdata = new CDATA("hello");
        JDOMNodePointer pointer = newPointer(cdata, Locale.ENGLISH);
        String path = callAsPath(pointer);

        assertEquals("/text()[1]", path);
    }

    @Test
    public void testProcessingInstructionProducesCorrectAxisAndTarget() {
        ProcessingInstruction pi = new ProcessingInstruction("my-target", "data");
        JDOMNodePointer pointer = newPointer(pi, Locale.ENGLISH);
        String path = callAsPath(pointer);

        assertEquals("/processing-instruction('my-target')[1]", path);
    }

    @Test
    public void testUnsupportedNodeTypeReturnsParentPathOnlyOrEmptyString() {
        Comment comment = new Comment("ignored");
        JDOMNodePointer pointer = newPointer(comment, Locale.ENGLISH);
        assertEquals("", callAsPath(pointer));
    }

    @Test
    public void testNestedTextPointerConcatenatesParentPath() {
        Element parentElement = new Element("parent");
        Document doc = new Document(parentElement);
        JDOMNodePointer parentPointer = newPointer(doc, Locale.ENGLISH);

        Text text = new Text("hello");
        parentElement.addContent(text);

        JDOMNodePointer textPointer = newPointer(parentPointer, text);

        assertEquals("/text()[1]", callAsPath(textPointer));
    }
}

