package org.apache.commons.jxpath.ri.parser;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.io.StringReader;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

import org.junit.Test;

public class JjFillTokenTests {

    private static XPathParserTokenManager newTokenManager(String input) {
        SimpleCharStream stream = new SimpleCharStream(new StringReader(input), 1, 1);
        return new XPathParserTokenManager(stream);
    }

    private static void setIntField(Object target, String fieldName, int value) throws Exception {
        Field f = XPathParserTokenManager.class.getDeclaredField(fieldName);
        f.setAccessible(true);
        f.setInt(target, value);
    }

    private static Token invokeJjFillToken(XPathParserTokenManager tm) throws Exception {
        Method m = XPathParserTokenManager.class.getDeclaredMethod("jjFillToken");
        m.setAccessible(true);
        return (Token) m.invoke(tm);
    }

    @Test
    public void fillsTokenForLiteralImageKind() throws Exception {
        XPathParserTokenManager tm = newTokenManager("abc");
        setIntField(tm, "jjmatchedKind", 6);

        Token token = invokeJjFillToken(tm);

        assertEquals(6, token.kind);
        assertEquals("/", token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(1, token.endColumn);
    }

    @Test
    public void fillsTokenForNonLiteralImageKindUsingInputImage() throws Exception {
        String input = "foo";
        XPathParserTokenManager tm = newTokenManager(input);
        setIntField(tm, "jjmatchedKind", 1);

        Token token = invokeJjFillToken(tm);

        assertEquals(1, token.kind);
        assertEquals(input, token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(1, token.endColumn);
    }

    @Test
    public void fillsTokenWithMultilinePositionInformation() throws Exception {
        String input = "ab\ncd";
        SimpleCharStream stream = new SimpleCharStream(new StringReader(input), 1, 1);
        stream.BeginToken();
        stream.readChar();
        stream.readChar();
        stream.readChar();

        XPathParserTokenManager tm = new XPathParserTokenManager(stream);
        setIntField(tm, "jjmatchedKind", 1);

        Token token = invokeJjFillToken(tm);

        assertEquals("ab\n", token.image);
        assertEquals(2, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(1, token.endColumn);
    }

    @Test
    public void supportsEmptyImageLiteralTokenKind() throws Exception {
        XPathParserTokenManager tm = newTokenManager("");
        setIntField(tm, "jjmatchedKind", 0);

        Token token = invokeJjFillToken(tm);

        assertEquals(0, token.kind);
        assertEquals("", token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(1, token.endColumn);
    }

    @Test
    public void throwsArrayIndexOutOfBoundsForNegativeMatchedKind() throws Exception {
        XPathParserTokenManager tm = newTokenManager("x");
        setIntField(tm, "jjmatchedKind", -1);

        try {
            invokeJjFillToken(tm);
        } catch (Exception e) {
            Throwable cause = e.getCause() != null ? e.getCause() : e;
            if (cause instanceof ArrayIndexOutOfBoundsException) {
                return;
            }
            throw e;
        }
    }

    @Test
    public void throwsArrayIndexOutOfBoundsForTooLargeMatchedKind() throws Exception {
        XPathParserTokenManager tm = newTokenManager("x");
        setIntField(tm, "jjmatchedKind", XPathParserTokenManager.jjstrLiteralImages.length);

        try {
            invokeJjFillToken(tm);
        } catch (Exception e) {
            Throwable cause = e.getCause() != null ? e.getCause() : e;
            if (cause instanceof ArrayIndexOutOfBoundsException) {
                return;
            }
            throw e;
        }
    }

    @Test
    public void tokenKindAndImageAreIndependentOfStreamAfterInvocation() throws Exception {
        String input = "xyz";
        XPathParserTokenManager tm = newTokenManager(input);
        setIntField(tm, "jjmatchedKind", 1);

        Token token = invokeJjFillToken(tm);

        assertEquals(1, token.kind);
        assertEquals(input, token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(1, token.endColumn);

        assertNull(null);
    }
}

package org.apache.commons.jxpath.ri.parser;

import org.junit.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.CharBuffer;

import static org.junit.Assert.*;

public class JjFillTokenTests {

    private static XPathParserTokenManager newTokenManager(String input) throws Exception {
        SimpleCharStream stream = new SimpleCharStream(new java.io.StringReader(input), 1, 1);
        return new XPathParserTokenManager(stream);
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field f = target.getClass().getDeclaredField(name);
        f.setAccessible(true);
        f.set(target, value);
    }

    private static Object getField(Object target, String name) throws Exception {
        Field f = target.getClass().getDeclaredField(name);
        f.setAccessible(true);
        return f.get(target);
    }

    private static Token invokeJjFillToken(XPathParserTokenManager tm) throws Exception {
        Method m = XPathParserTokenManager.class.getDeclaredMethod("jjFillToken");
        m.setAccessible(true);
        return (Token) m.invoke(tm);
    }

    @Test
    public void testFillTokenUsesLiteralImageWhenAvailable() throws Exception {
        XPathParserTokenManager tm = newTokenManager("and");
        setField(tm, "jjmatchedKind", 27); // "or" in jjstrLiteralImages, but any non-null image token works
        setField(tm, "jjmatchedPos", 1);

        Token token = invokeJjFillToken(tm);

        assertNotNull(token);
        assertEquals(27, token.kind);
        assertEquals(XPathParserTokenManager.jjstrLiteralImages[27], token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(3, token.endColumn);
    }

    @Test
    public void testFillTokenUsesInputImageWhenLiteralImageIsNull() throws Exception {
        String input = "abc";
        XPathParserTokenManager tm = newTokenManager(input);
        setField(tm, "jjmatchedKind", 1);
        setField(tm, "jjmatchedPos", input.length() - 1);

        Token token = invokeJjFillToken(tm);

        assertNotNull(token);
        assertEquals(1, token.kind);
        assertEquals(input, token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(3, token.endColumn);
    }

    @Test
    public void testFillTokenPreservesCoordinatesFromInputStream() throws Exception {
        String input = "line1\nline2";
        SimpleCharStream stream = new SimpleCharStream(new java.io.StringReader(input), 1, 1);
        XPathParserTokenManager tm = new XPathParserTokenManager(stream);

        Field lineBufField = SimpleCharStream.class.getDeclaredField("lineBuf");
        lineBufField.setAccessible(true);
        int[] lineBuf = (int[]) lineBufField.get(stream);
        assertTrue(lineBuf.length > 2);

        int pos = input.indexOf("line2") + "line2".length() - 1;
        setField(stream, "bufline", lineBuf);
        setField(stream, "bufcolumn", new int[lineBuf.length]);
        setField(stream, "tokenBegin", input.indexOf("line2"));
        setField(stream, "bufpos", pos);
        setField(stream, "line", 2);
        setField(stream, "column", 5);
        setField(tm, "jjmatchedKind", 1);
        setField(tm, "jjmatchedPos", "line2".length() - 1);

        Token token = invokeJjFillToken(tm);

        assertEquals(2, token.beginLine);
        assertTrue(token.beginColumn >= 1);
        assertEquals(2, token.endLine);
        assertEquals(5, token.endColumn);
    }

    @Test
    public void testFillTokenHandlesEmptyLiteralImageAsValidImage() throws Exception {
        XPathParserTokenManager tm = newTokenManager("");
        setField(tm, "jjmatchedKind", 0);
        setField(tm, "jjmatchedPos", -1);

        Token token = invokeJjFillToken(tm);

        assertNotNull(token);
        assertEquals(0, token.kind);
        assertEquals("", token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(0, token.endColumn);
    }

    @Test
    public void testFillTokenReturnsDistinctTokenInstances() throws Exception {
        XPathParserTokenManager tm = newTokenManager("abc");
        setField(tm, "jjmatchedKind", 1);
        setField(tm, "jjmatchedPos", 2);

        Token t1 = invokeJjFillToken(tm);
        Token t2 = invokeJjFillToken(tm);

        assertNotNull(t1);
        assertNotNull(t2);
        assertNotSame(t1, t2);
    }

    @Test
    public void testNewTokenManagerRejectsStaticCharStreamConfiguration() throws Exception {
        Field staticFlag = SimpleCharStream.class.getDeclaredField("staticFlag");
        staticFlag.setAccessible(true);
        boolean old = staticFlag.getBoolean(null);
        staticFlag.setBoolean(null, true);
        try {
            try {
                newTokenManager("abc");
                fail("Expected Error due to static CharStream usage.");
            } catch (Error expected) {
                assertTrue(expected.getMessage().contains("static CharStream"));
            }
        } finally {
            staticFlag.setBoolean(null, old);
        }
    }

