package org.apache.commons.jxpath.ri.parser;

import org.junit.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.Assert.*;

public class JjFillTokenTests {

    private static class TestableXPathParserTokenManager extends XPathParserTokenManager {
        TestableXPathParserTokenManager(SimpleCharStream stream) {
            super(stream);
        }

        Token callJjFillToken() {
            return jjFillToken();
        }
    }

    private static SimpleCharStream newStream(String input) {
        return new SimpleCharStream(new java.io.StringReader(input), 1, 1);
    }

    private static void setIntField(Object target, String fieldName, int value) throws Exception {
        Field f = target.getClass().getSuperclass().getDeclaredField(fieldName);
        f.setAccessible(true);
        f.setInt(target, value);
    }

    private static int getTokenManagerKind(Object target) throws Exception {
        Field f = target.getClass().getSuperclass().getDeclaredField("jjmatchedKind");
        f.setAccessible(true);
        return f.getInt(target);
    }

    private static void setTokenManagerKind(Object target, int value) throws Exception {
        Field f = target.getClass().getSuperclass().getDeclaredField("jjmatchedKind");
        f.setAccessible(true);
        f.setInt(target, value);
    }

    @Test
    public void fillsTokenWithLiteralImageAndPosition() throws Exception {
        TestableXPathParserTokenManager tm = new TestableXPathParserTokenManager(newStream("+"));
        setTokenManagerKind(tm, 9); // "+"
        setIntField(tm, "beginLine", 3);
        setIntField(tm, "beginColumn", 5);
        setIntField(tm, "endLine", 3);
        setIntField(tm, "endColumn", 5);

        Token token = tm.callJjFillToken();

        assertNotNull(token);
        assertEquals(9, token.kind);
        assertEquals("+", token.image);
        assertEquals(3, token.beginLine);
        assertEquals(5, token.beginColumn);
        assertEquals(3, token.endLine);
        assertEquals(5, token.endColumn);
    }

    @Test
    public void fillsTokenUsingInputStreamImageWhenLiteralImageIsNull() throws Exception {
        String input = "abc123";
        TestableXPathParserTokenManager tm = new TestableXPathParserTokenManager(newStream(input));
        setTokenManagerKind(tm, 1); // jjstrLiteralImages[1] == null
        setIntField(tm, "beginLine", 1);
        setIntField(tm, "beginColumn", 1);
        setIntField(tm, "endLine", 1);
        setIntField(tm, "endColumn", input.length());

        Token token = tm.callJjFillToken();

        assertNotNull(token);
        assertEquals(1, token.kind);
        assertEquals(input, token.image);
        assertEquals(1, token.beginLine);
        assertEquals(1, token.beginColumn);
        assertEquals(1, token.endLine);
        assertEquals(input.length(), token.endColumn);
    }

    @Test
