        setTokenManagerKind(tm, 20); // null literal image
        setIntField(tm, "beginLine", 2);
        setIntField(tm, "beginColumn", 4);
        setIntField(tm, "endLine", 2);
        setIntField(tm, "endColumn", 9);

        Token token = tm.callJjFillToken();

        assertEquals(input, token.image);
        assertEquals(2, token.beginLine);
        assertEquals(4, token.beginColumn);
        assertEquals(2, token.endLine);
        assertEquals(9, token.endColumn);
    }

    @Test
