        TestableXPathParserTokenManager tm = new TestableXPathParserTokenManager(newStream("or"));
        setTokenManagerKind(tm, 28); // "or"
        setIntField(tm, "beginLine", 7);
        setIntField(tm, "beginColumn", 11);
        setIntField(tm, "endLine", 7);
        setIntField(tm, "endColumn", 12);

        Token token = tm.callJjFillToken();

        assertEquals(28, token.kind);
        assertEquals("or", token.image);
    }

