package org.apache.commons.jxpath.ri.model.jdom;

import org.jdom.Attribute;
import org.jdom.Content;
import org.jdom.Element;
import org.jdom.Namespace;
import org.junit.Test;

import java.util.Locale;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class FindEnclosingAttributeTests {

    private static final Namespace NS = Namespace.getNamespace("p", "urn:test");
    private static final Namespace OTHER_NS = Namespace.getNamespace("q", "urn:other");

    private static final class ExposedJDOMNodePointer extends JDOMNodePointer {
        private ExposedJDOMNodePointer() {
            super((Object) null, (Locale) null);
        }

        static String callFindEnclosingAttribute(Object n, String attrName, Namespace ns) {
            return findEnclosingAttribute(n, attrName, ns);
        }
    }

    @Test
    public void returnsCurrentElementAttributeWhenPresentAndNonEmpty() {
        Element element = new Element("item", NS);
        element.setAttribute("id", "current", NS);

        assertEquals("current", ExposedJDOMNodePointer.callFindEnclosingAttribute(element, "id", NS));
    }

    @Test
    public void usesParentAttributeWhenCurrentElementDoesNotHaveMatchingAttribute() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "parentValue", NS);

        Element child = new Element("child", NS);
        parent.addContent(child);

        assertEquals("parentValue", ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "id", NS));
    }

    @Test
    public void prefersCurrentElementAttributeOverParentAttribute() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "parentValue", NS);

        Element child = new Element("child", NS);
        child.setAttribute("id", "childValue", NS);
        parent.addContent(child);

        assertEquals("childValue", ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "id", NS));
    }

    @Test
    public void returnsNullWhenCurrentAttributeIsEmptyEvenIfParentHasNonEmptyAttribute() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "parentValue", NS);

        Element child = new Element("child", NS);
        child.setAttribute("id", "", NS);
        parent.addContent(child);

        assertNull(ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "id", NS));
    }

    @Test
    public void returnsNullWhenParentAttributeIsEmptyAndCurrentAttributeMissing() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "", NS);

        Element child = new Element("child", NS);
        parent.addContent(child);

        assertNull(ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "id", NS));
    }

    @Test
    public void returnsNullWhenOnlyGrandparentHasMatchingAttribute() {
        Element grandparent = new Element("grandparent", NS);
        grandparent.setAttribute("id", "grandparentValue", NS);

        Element parent = new Element("parent", NS);
        Element child = new Element("child", NS);

        grandparent.addContent(parent);
        parent.addContent(child);

        assertNull(ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "id", NS));
    }

    @Test
    public void respectsNamespaceAndDoesNotUseAttributeFromDifferentNamespace() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "wrongNsValue", OTHER_NS);

        Element child = new Element("child", NS);
        parent.addContent(child);

        assertNull(ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "id", NS));
    }

    @Test
    public void returnsNullForNonElementInput() {
        assertNull(ExposedJDOMNodePointer.callFindEnclosingAttribute("notAnElement", "id", NS));
    }

    @Test
    public void returnsNullForAttributeNameThatDoesNotExist() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "parentValue", NS);

        Element child = new Element("child", NS);
        parent.addContent(child);

        assertNull(ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "missing", NS));
    }

    @Test
    public void returnsCurrentValueWhenAttributeNameIsSharedButNamespaceDiffersOnParent() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("role", "parentRole", OTHER_NS);

        Element child = new Element("child", NS);
        child.setAttribute("role", "childRole", NS);
        parent.addContent(child);

        assertEquals("childRole", ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "role", NS));
    }

    @Test
    public void returnsNullWhenAttributeValueIsWhitespaceOnly() {
        Element element = new Element("item", NS);
        element.setAttribute("id", " ", NS);

        assertEquals(" ", ExposedJDOMNodePointer.callFindEnclosingAttribute(element, "id", NS));
    }

    @Test
    public void handlesNullNamespaceLookupAgainstUnqualifiedAttributes() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "parentValue");

        Element child = new Element("child", NS);
        parent.addContent(child);

        assertEquals("parentValue", ExposedJDOMNodePointer.callFindEnclosingAttribute(child, "id", null));
    }

    @Test
    public void handlesContentChildWithElementParent() {
        Element parent = new Element("parent", NS);
        parent.setAttribute("id", "parentValue", NS);

        Element child = new Element("child", NS);
        parent.addContent(child);

        Content contentNode = child.getContent(0);

        assertEquals("parentValue", ExposedJDOMNodePointer.callFindEnclosingAttribute(contentNode, "id", NS));
    }

    @Test
    public void returnsNullForDetachedElementWithNoParent() {
        Element detached = new Element("detached", NS);

        assertNull(ExposedJDOMNodePointer.callFindEnclosingAttribute(detached, "id", NS));
    }
}

