package org.apache.commons.jxpath.util;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class IterateTests {

    @Test
    public void nullCollectionReturnsEmptyIterator() {
        Iterator<?> iterator = ValueUtils.iterate(null);

        assertFalse(iterator.hasNext());
    }

    @Test
    public void collectionReturnsAllElementsInIterationOrder() {
        List<String> input = Arrays.asList("a", "b", "c");

        Iterator<?> iterator = ValueUtils.iterate(input);

        List<Object> actual = new ArrayList<Object>();
        while (iterator.hasNext()) {
            actual.add(iterator.next());
        }

        assertEquals(Arrays.asList("a", "b", "c"), actual);
    }

    @Test
    public void emptyArrayReturnsEmptyIterator() {
        String[] input = new String[0];

        Iterator<?> iterator = ValueUtils.iterate(input);

        assertFalse(iterator.hasNext());
    }

    @Test
    public void objectArrayReturnsOnlyFirstElement() {
        String[] input = new String[] {"first", "second", "third"};

        Iterator<?> iterator = ValueUtils.iterate(input);

        List<Object> actual = new ArrayList<Object>();
        while (iterator.hasNext()) {
            actual.add(iterator.next());
        }

        assertEquals(Collections.singletonList("first"), actual);
    }

    @Test
    public void primitiveArrayReturnsOnlyFirstElementBoxed() {
        int[] input = new int[] {7, 8, 9};

        Iterator<?> iterator = ValueUtils.iterate(input);

        List<Object> actual = new ArrayList<Object>();
        while (iterator.hasNext()) {
            actual.add(iterator.next());
        }

        assertEquals(Collections.singletonList(Integer.valueOf(7)), actual);
    }

    @Test
    public void singleNonCollectionNonArrayObjectIsWrappedAsSingleton() {
        Object input = new Object();

        Iterator<?> iterator = ValueUtils.iterate(input);

        List<Object> actual = new ArrayList<Object>();
        while (iterator.hasNext()) {
            actual.add(iterator.next());
        }

        assertEquals(1, actual.size());
        assertEquals(input, actual.get(0));
    }

    @Test
    public void iteratorReturnedFromCollectionIsLiveViewOfUnderlyingCollection() {
        List<String> input = new ArrayList<String>(Arrays.asList("x", "y"));

        Iterator<?> iterator = ValueUtils.iterate(input);
        input.add("z");

        List<Object> actual = new ArrayList<Object>();
        while (iterator.hasNext()) {
            actual.add(iterator.next());
        }

        assertEquals(Arrays.asList("x", "y", "z"), actual);
    }
}

package org.apache.commons.jxpath.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import org.junit.Test;

public class IterateTests {

    @Test
    public void testIterateNullReturnsEmptyIterator() {
        Iterator iterator = ValueUtils.iterate(null);
        assertNotNull(iterator);
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testIterateEmptyArrayReturnsEmptyIterator() {
        Iterator iterator = ValueUtils.iterate(new Object[0]);
        assertNotNull(iterator);
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testIterateSingleElementArrayReturnsSingleElement() {
        String[] array = new String[] {"a"};
        Iterator iterator = ValueUtils.iterate(array);

        assertTrueSequence(iterator, Arrays.asList("a"));
    }

    @Test
    public void testIterateMultiElementArrayReturnsAllElements() {
        Integer[] array = new Integer[] {1, 2, 3};
        Iterator iterator = ValueUtils.iterate(array);

        assertTrueSequence(iterator, Arrays.asList(1, 2, 3));
    }

    @Test
    public void testIteratePrimitiveArrayReturnsAllElements() {
        int[] array = new int[] {4, 5, 6};
        Iterator iterator = ValueUtils.iterate(array);

        assertTrueSequence(iterator, Arrays.asList(4, 5, 6));
    }

    @Test
    public void testIterateCollectionReturnsItsIterator() {
        List<String> list = new LinkedList<String>();
        list.add("x");
        list.add("y");

        Iterator iterator = ValueUtils.iterate(list);
        assertTrueSequence(iterator, Arrays.asList("x", "y"));
    }

    @Test
    public void testIterateSingleObjectReturnsSingletonIterator() {
        Object value = new Object();
        Iterator iterator = ValueUtils.iterate(value);

        assertTrue(iterator.hasNext());
        assertEquals(value, iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testIterateStringReturnsSingletonIteratorNotCharacters() {
        String value = "abc";
        Iterator iterator = ValueUtils.iterate(value);

        assertTrue(iterator.hasNext());
        assertEquals(value, iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testReturnedIteratorIsExhaustiveAndStableForCollection() {
        List<String> list = new ArrayList<String>();
        list.add("a");
        list.add("b");

        Iterator iterator = ValueUtils.iterate(list);
        assertEquals("a", iterator.next());
        list.add("c");

        assertEquals("b", iterator.next());
        assertEquals("c", iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testReturnedIteratorIsIndependentForArraySnapshotBehavior() {
        String[] array = new String[] {"first", "second"};
        Iterator iterator = ValueUtils.iterate(array);

        array[0] = "changed";
        assertTrue(iterator.hasNext());
        assertEquals("first", iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testIterateNullDoesNotThrow() {
        try {
            Iterator iterator = ValueUtils.iterate(null);
            assertNotNull(iterator);
        } catch (Throwable t) {
            fail("iterate(null) should not throw, but threw: " + t);
        }
    }

    private static void assertTrueSequence(Iterator iterator, List expected) {
        for (Object expectedItem : expected) {
            assertTrue(iterator.hasNext());
            assertEquals(expectedItem, iterator.next());
        }
        assertFalse(iterator.hasNext());
    }

    private static void assertTrue(boolean condition) {
        if (!condition) {
            fail();
        }
    }
}

