        assertEquals("/", pointer.asPath());
    }

    @Test
    public void testAsPathDelegatesToParentPath() {
        DynaBeanPointer parent = new DynaBeanPointer(new QName("parent"), mockDynaBean(), Locale.ENGLISH);
        DynaBeanPointer child = new DynaBeanPointer(parent, new QName("child"), mockDynaBean());

        assertSame(parent.asPath(), child.asPath());
        assertEquals(parent.asPath(), child.asPath());
    }

    @Test
    public void testAsPathReturnsExactParentPathForNestedPointers() {
        DynaBeanPointer root = new DynaBeanPointer(new QName("root"), mockDynaBean(), Locale.ENGLISH);
        DynaBeanPointer level1 = new DynaBeanPointer(root, new QName("level1"), mockDynaBean());
        DynaBeanPointer level2 = new DynaBeanPointer(level1, new QName("level2"), mockDynaBean());

        assertEquals("/", root.asPath());
        assertEquals(root.asPath(), level1.asPath());
        assertEquals(level1.asPath(), level2.asPath());
    }

    @Test
    public void testAsPathDoesNotDependOnDynaBeanValue() {
        DynaBeanPointer pointer1 = new DynaBeanPointer(new QName("bean1"), mockDynaBean(), Locale.ENGLISH);
        DynaBeanPointer pointer2 = new DynaBeanPointer(new QName("bean2"), mockDynaBean(), Locale.FRANCE);

        assertEquals("/", pointer1.asPath());
        assertEquals("/", pointer2.asPath());
